"""TLS check evaluation and rule interpretation service."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from runner.tls import TLSProbeResult

TLS_CHECK_SCHEMA_VERSION = 1
TLS_ADAPTER_VERSION = "tls-prober-v1"


@dataclass(frozen=True)
class CheckFinding:
    """Standard rule finding generated by technical interpretation."""

    rule_id: str
    rule_version: str
    subject_key: str
    severity: str  # 'informational', 'low', 'medium', 'high', 'critical'
    confidence: str  # 'low', 'medium', 'high', 'unknown'
    attribution: str  # 'hostname_supported', 'ip_only', 'shared_infrastructure', 'unknown'
    message_key: str
    message_parameters: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        """Convert finding to dictionary."""
        return {
            "rule_id": self.rule_id,
            "rule_version": self.rule_version,
            "subject_key": self.subject_key,
            "severity": self.severity,
            "confidence": self.confidence,
            "attribution": self.attribution,
            "message_key": self.message_key,
            "message_parameters": self.message_parameters,
        }


@dataclass(frozen=True)
class TLSCheckEvaluation:
    """Standard evaluation result for a TLS endpoint probe."""

    status: str  # 'succeeded', 'failed', 'skipped'
    reason_code: str | None
    verdict: str  # 'valid', 'invalid', 'unknown'
    should_skip_http: bool
    skip_reason: str | None
    findings: list[CheckFinding]
    payload: dict[str, Any]
    schema_version: int = TLS_CHECK_SCHEMA_VERSION
    adapter_version: str = TLS_ADAPTER_VERSION


def evaluate_tls_check(
    probe_result: TLSProbeResult,
    expiry_warning_days: int = 30,
    rule_version: str = "v1",
) -> TLSCheckEvaluation:
    """Evaluate a TLSProbeResult, emit findings, and determine downstream check eligibility.

    Rules enforced:
    - TLS_VALIDATION_FAILED: live endpoint fails trust, name, or time validity (COL-02).
      Halts dependent active HTTP collection on this endpoint.
    - TLS_EXPIRING_SOON: valid certificate expires within warning window (Severity: Low).
    """
    subject_key = f"endpoint:{probe_result.hostname}:{probe_result.port}"
    findings: list[CheckFinding] = []
    payload = probe_result.to_dict()

    if not probe_result.is_valid:
        # Determine specific reason code
        reason_code = "invalid_tls"
        if "TIMEOUT" in probe_result.failure_reasons:
            reason_code = "timeout"
        elif "CONNECTION_REFUSED" in probe_result.failure_reasons:
            reason_code = "connection_refused"
        elif "CONNECTION_FAILED" in str(probe_result.failure_reasons):
            reason_code = "connection_failed"

        # Emit TLS_VALIDATION_FAILED finding if certificate/handshake failed
        findings.append(
            CheckFinding(
                rule_id="TLS_VALIDATION_FAILED",
                rule_version=rule_version,
                subject_key=subject_key,
                severity="medium",
                confidence="high",
                attribution="hostname_supported",
                message_key="rules.tls_validation_failed",
                message_parameters={
                    "hostname": probe_result.hostname,
                    "port": probe_result.port,
                    "failure_reasons": probe_result.failure_reasons,
                },
            )
        )

        return TLSCheckEvaluation(
            status="failed",
            reason_code=reason_code,
            verdict="invalid",
            should_skip_http=True,
            skip_reason="skipped_due_to_tls_failure",
            findings=findings,
            payload=payload,
        )

    # Valid TLS endpoint
    if (
        probe_result.days_until_expiration is not None
        and probe_result.days_until_expiration <= expiry_warning_days
    ):
        findings.append(
            CheckFinding(
                rule_id="TLS_EXPIRING_SOON",
                rule_version=rule_version,
                subject_key=subject_key,
                severity="low",
                confidence="high",
                attribution="hostname_supported",
                message_key="rules.tls_expiring_soon",
                message_parameters={
                    "hostname": probe_result.hostname,
                    "port": probe_result.port,
                    "days_remaining": probe_result.days_until_expiration,
                    "not_after": probe_result.not_after.isoformat()
                    if probe_result.not_after
                    else None,
                },
            )
        )

    return TLSCheckEvaluation(
        status="succeeded",
        reason_code=None,
        verdict="valid",
        should_skip_http=False,
        skip_reason=None,
        findings=findings,
        payload=payload,
    )
